import './cloud-sync.js';
import{ADDITION_TRACKS,ADDITION_CHAIN,ADDITION_DIAGNOSTIC,recommendAdditionTrack,bridgeAddition,compensateSubtraction,inverseCheck,solveStory,createBlankAdditionLearner}from'./addition-data.js';

const $=s=>document.querySelector(s),storageKey='mathlab-addition-v1',memory={};
function blankStore(){return{a:createBlankAdditionLearner(),b:createBlankAdditionLearner(),learner:'a'}}
function readStore(){try{return JSON.parse(localStorage.getItem(storageKey))||blankStore()}catch{return memory.data||blankStore()}}
let store=readStore(),learner=store.learner||'a',state=store[learner]||createBlankAdditionLearner(),hintLevel=0,errors=0,sessionMissionId=null,work={};
function ensureState(){const blank=createBlankAdditionLearner();state={...blank,...state,diagnostic:{...blank.diagnostic,...state.diagnostic},missions:{...state.missions},sessions:{...state.sessions},evidence:{...blank.evidence,...state.evidence},family:{...blank.family,...state.family}}}
function save(){state.updatedAt=new Date().toISOString();store={...readStore(),[learner]:state,learner};memory.data=store;try{localStorage.setItem(storageKey,JSON.stringify(store));$('#saveStatus').textContent='Saved offline · cloud sync follows parent sign-in'}catch{$('#saveStatus').textContent='Progress lasts until this page closes.'}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function feedback(text,type=''){const el=$('#feedback');el.textContent=text;el.className='feedback '+type}
function track(){return ADDITION_TRACKS[state.track||'explorer']}
function done(i){return Boolean(state.missions[ADDITION_CHAIN.missions[i].id]?.complete)}
function unlocked(i){return i===0||done(i-1)}
function mark(dim,independent=true){if(independent)state.evidence[dim]='independent';else if(state.evidence[dim]==='unknown')state.evidence[dim]='learning'}
function loadSession(id){sessionMissionId=id;const saved=state.sessions[id]||{errors:0,hints:0,work:{}};errors=Number(saved.errors)||0;hintLevel=Number(saved.hints)||0;work=saved.work||{}}
function saveSession(nextWork=work){if(!sessionMissionId)return;work=nextWork;state.sessions[sessionMissionId]={errors,hints:hintLevel,work};save()}
function miss(message){errors++;saveSession();feedback(message,'try')}
function complete(i,dims=[],pending=false,preview=false){const m=ADDITION_CHAIN.missions[i];state.missions[m.id]={complete:!preview,preview,errors,hints:hintLevel,completedAt:new Date().toISOString(),track:state.track};dims.forEach(d=>mark(d,errors===0&&hintLevel===0&&!preview));if(pending){state.retestDue=Date.now()+20*60*60*1000;state.evidence.explanation=state.evidence.explanation==='unknown'?'learning':state.evidence.explanation}if(!preview&&i<4)state.activeMission=i+1;delete state.sessions[m.id];errors=0;hintLevel=0;work={};sessionMissionId=null;save();setTimeout(render,450)}
function hint(text){return hintLevel?`<div class="hint-box">${esc(text)}</div>`:''}
function controls(){return `<div class="answer-row"><button class="secondary" data-action="hint">Give me one hint</button></div>`}
function uniqueChoices(correct,candidates){return [...new Set([correct,...candidates])].slice(0,3)}
function choiceGrid(values,attr,label=x=>String(x)){return `<div class="answer-grid">${values.map(v=>`<button class="choice" data-${attr}="${v}">${esc(label(v))}</button>`).join('')}</div>`}
function jumpModel(start,jumps,end){return `<div class="jump-model"><span class="jump-node">${start}</span>${jumps.map(j=>`<span class="jump-step"><b>${j>0?'+':''}${j}</b><i>→</i></span>`).join('')}<span class="jump-node end">${end}</span></div>`}

function renderDiagnostic(){const d=state.diagnostic;if(d.index>=ADDITION_DIAGNOSTIC.length){state.track=state.track||recommendAdditionTrack(d.score);const t=track();$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">STARTING DEPTH FOUND</p><h3>${t.label}</h3><p>${t.description}</p><p class="microcopy">This chooses useful numbers. It is not a grade label.</p><button class="primary" data-action="start">Try a friendly-number strategy →</button></div>`;return}const q=ADDITION_DIAGNOSTIC[d.index];$('#activity').innerHTML=`<div class="diagnostic-progress"><span style="width:${d.index/ADDITION_DIAGNOSTIC.length*100}%"></span></div><p class="eyebrow">QUESTION ${d.index+1} OF ${ADDITION_DIAGNOSTIC.length}</p><h3>${esc(q.prompt)}</h3><div class="answer-grid">${q.choices.map((x,i)=>`<button class="choice" data-diagnostic="${i}">${esc(x)}</button>`).join('')}</div><p class="microcopy">No timer. A grown-up may read the words aloud.</p>`;document.querySelectorAll('[data-diagnostic]').forEach(b=>b.onclick=()=>{const correct=Number(b.dataset.diagnostic)===q.answer;d.answers.push({id:q.id,correct});if(correct)d.score++;d.index++;feedback(correct?'That relationship is clear.':q.why,correct?'good':'try');save();setTimeout(()=>{feedback('');render()},500)})}
function renderBridge(){const p=track().addition;if(!work.bridge){const choices=uniqueChoices(p.bridge,[p.bridge+1,Math.max(1,p.bridge-1)]);$('#activity').innerHTML=`<p class="eyebrow">CHOOSE THE FIRST JUMP</p><h3>${p.a} + ${p.b}</h3><p class="prompt">How much of ${p.b} should move first so ${p.a} lands on ${p.friendly}?</p>${jumpModel(p.a,['?'],p.friendly)}${choiceGrid(choices,'bridge')}${controls()}${hint(`${p.a} needs ${p.bridge} more to reach ${p.friendly}. Split ${p.b} into ${p.bridge} and the amount left.`)}`;document.querySelectorAll('[data-bridge]').forEach(b=>b.onclick=()=>{if(Number(b.dataset.bridge)===p.bridge){work={...work,bridge:true};saveSession();feedback(`Yes. ${p.a} + ${p.bridge} = ${p.friendly}. What remains?`,'good');setTimeout(renderMission,350)}else miss(`That jump does not land on ${p.friendly}. Find the distance from ${p.a} to ${p.friendly}.`)})}else{const choices=uniqueChoices(p.remainder,[p.remainder+1,Math.max(0,p.remainder-1)]);$('#activity').innerHTML=`<p class="eyebrow">KEEP THE TOTAL</p><h3>${p.a} + ${p.b} = ${p.a} + ${p.bridge} + ?</h3><p class="prompt">You moved ${p.bridge} from ${p.b}. How much is still left to add?</p>${jumpModel(p.a,[p.bridge,'?'],p.result)}${choiceGrid(choices,'remainder')}${controls()}${hint(`Keep the full ${p.b}: ${p.bridge} + ${p.remainder} = ${p.b}.`)}`;document.querySelectorAll('[data-remainder]').forEach(b=>b.onclick=()=>{if(Number(b.dataset.remainder)===p.remainder&&bridgeAddition(p)===p.result){feedback(`${p.a} + ${p.b} became ${p.friendly} + ${p.remainder}. The total is still ${p.result}.`,'good');complete(1,['friendly','decompose'])}else miss(`The two parts must still make ${p.b}. One part is ${p.bridge}.`)})}}
function renderSubtract(){const p=track().subtraction;if(!work.friendly){const choices=uniqueChoices(p.friendlySub,[p.sub,p.friendlySub+(p.friendlySub>=10?10:1)]);$('#activity').innerHTML=`<p class="eyebrow">MAKE THE SUBTRACTION EASIER</p><h3>${p.start} − ${p.sub}</h3><p class="prompt">Which nearby amount is easiest to subtract first?</p>${choiceGrid(choices,'friendly-sub',v=>`Subtract ${v} first`)}${controls()}${hint(`Choose a nearby ${p.friendlySub>=100?'hundred':'ten'}: ${p.friendlySub}. Then correct the small difference.`)}`;document.querySelectorAll('[data-friendly-sub]').forEach(b=>b.onclick=()=>{if(Number(b.dataset.friendlySub)===p.friendlySub){work={...work,friendly:true};saveSession();feedback(`${p.start} − ${p.friendlySub} is easier. Now account for the difference between ${p.friendlySub} and ${p.sub}.`,'good');setTimeout(renderMission,350)}else miss(`Look for a nearby round number that makes the subtraction simpler.`)})}else{const correction=p.friendlySub-p.sub,removedTooMuch=correction>0,choices=uniqueChoices(p.adjust,[-p.adjust,0]),reason=removedTooMuch?`You removed ${correction} too much.`:`You still need to remove ${Math.abs(correction)} more.`,help=removedTooMuch?`Add the extra ${correction} back.`:`Subtract the remaining ${Math.abs(correction)}.`;$('#activity').innerHTML=`<p class="eyebrow">KEEP THE VALUE BALANCED</p><h3>${p.start} − ${p.sub}</h3><p class="prompt">After subtracting ${p.friendlySub}, ${reason} What correction keeps the original value?</p>${jumpModel(p.start,[-p.friendlySub,'?'],p.result)}${choiceGrid(choices,'adjust',v=>v>0?`Add back ${v}`:v<0?`Subtract ${Math.abs(v)} more`:'Make no correction')}${controls()}${hint(help)}`;document.querySelectorAll('[data-adjust]').forEach(b=>b.onclick=()=>{if(Number(b.dataset.adjust)===p.adjust&&compensateSubtraction(p)===p.result){feedback(`${p.start} − ${p.friendlySub} ${p.adjust>=0?'+':'−'} ${Math.abs(p.adjust)} = ${p.result}. The value matches ${p.start} − ${p.sub}.`,'good');complete(2,['friendly','decompose'])}else miss(removedTooMuch?`Subtracting ${p.friendlySub} removed too much, so add ${correction} back.`:`Subtracting ${p.friendlySub} did not remove all ${p.sub}, so subtract ${Math.abs(correction)} more.`)})}}
function renderCheck(){const p=track().check;if(!work.checkFound){$('#activity').innerHTML=`<p class="eyebrow">IMMEDIATE APPLICATION · ERROR DETECTIVE</p><h3>A student says ${p.start} − ${p.sub} = ${p.wrong}.</h3><p class="prompt">Which calculation tests this exact claim?</p><div class="error-card"><strong>Claim</strong><span>${p.start} − ${p.sub} = ${p.wrong}</span></div><div class="answer-grid"><button class="choice" data-check="correct">${p.wrong} + ${p.sub} = ${p.wrong+p.sub}. Compare that with ${p.start}.</button><button class="choice" data-check="wrong">${p.start} + ${p.sub} = ${p.start+p.sub}. A larger result proves the claim.</button><button class="choice" data-check="wrong">${p.wrong} is smaller than ${p.start}, so the claim works.</button></div>${controls()}${hint(`Use the exact inverse: claimed difference + amount removed should rebuild ${p.start}.`)}`;document.querySelectorAll('[data-check]').forEach(b=>b.onclick=()=>{if(b.dataset.check==='correct'&&!inverseCheck(p.start,p.sub,p.wrong)){work={...work,checkFound:true};saveSession();feedback(`${p.wrong} + ${p.sub} = ${p.wrong+p.sub}, so the claim does not rebuild ${p.start}. Now repair it.`,'good');setTimeout(renderMission,350)}else miss('Test the exact claimed difference by adding back the amount removed.')})}else{const choices=uniqueChoices(p.result,[p.wrong,p.result+10]);$('#activity').innerHTML=`<p class="eyebrow">REPAIR THE CLAIM</p><h3>${p.start} − ${p.sub} = ?</h3><p class="prompt">Which difference passes the inverse check by rebuilding ${p.start}?</p>${choiceGrid(choices,'repair',v=>`${v} because ${v} + ${p.sub} = ${v+p.sub}`)}${controls()}${hint(`Find the value that makes ? + ${p.sub} = ${p.start}.`)}`;document.querySelectorAll('[data-repair]').forEach(b=>b.onclick=()=>{const answer=Number(b.dataset.repair);if(answer===p.result&&inverseCheck(p.start,p.sub,answer)){feedback(`${p.result} is proven: ${p.result} + ${p.sub} = ${p.start}. You used the inverse on a changed problem.`,'good');complete(3,['inverse','explanation'],true)}else miss(`That check gives ${answer+p.sub}, not ${p.start}.`)})}}
function renderFresh(){const due=state.retestDue||Date.now()+20*60*60*1000,ready=Date.now()>=due;if(!ready&&!state.previewFresh){const hours=Math.max(1,Math.ceil((due-Date.now())/3600000));$('#activity').innerHTML=`<div class="lock-card"><p class="eyebrow">FRESH CHECK</p><strong>Return after the strategy has faded from memory.</strong><p>About ${hours} hours remain. Waiting helps us see whether the idea is stable.</p><button class="secondary" data-action="preview">Preview for family review</button><p class="microcopy">The preview uses different numbers and will not count as delayed evidence.</p></div>`;return}const problem=ready?track().fresh.challenge:track().fresh.preview,answer=solveStory(problem),choices=uniqueChoices(answer,[answer+10,Math.max(0,answer-10)]);$('#activity').innerHTML=`<p class="eyebrow">${ready?'DELAYED CHECK · NEW STORY':'FAMILY PREVIEW · NOT DELAYED EVIDENCE'}</p><h3>${esc(problem.story)}</h3><p class="prompt">What is the result of ${problem.a} ${problem.op} ${problem.b}?</p>${choiceGrid(choices,'fresh')}<div id="freshWhy" hidden><p class="prompt">Which strategy keeps every part of this exact problem balanced?</p><div class="answer-grid">${[problem.strategy,...problem.decoys].map((text,i)=>`<button class="choice" data-fresh-strategy="${i===0?'correct':'wrong'}">${esc(text)}</button>`).join('')}</div></div>${controls()}${hint(`Look for a nearby friendly number. Every moved, added, or removed amount must appear in the equation.`)}`;let accepted=false;document.querySelectorAll('[data-fresh]').forEach(b=>b.onclick=()=>{if(Number(b.dataset.fresh)===answer){accepted=true;$('#freshWhy').hidden=false;feedback('The result is right. Now prove it with steps that use these exact numbers.','good')}else miss('Estimate first, then use a friendly number and check whether your answer is reasonable.')});document.querySelectorAll('[data-fresh-strategy]').forEach(b=>b.onclick=()=>{if(!accepted)return;if(b.dataset.freshStrategy==='correct'){feedback(ready?'You solved and justified a changed problem with number-specific steps.':'Preview complete. Return later for fresh evidence.','good');complete(4,['friendly','decompose','explanation'],false,!ready)}else miss('Track every part of the original number. A moved amount cannot disappear or be counted twice.')})}
function renderComplete(i){const m=ADDITION_CHAIN.missions[i];$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">MISSION COMPLETE</p><h3>${esc(m.title)}</h3><p>Your work is saved for ${learner==='a'?'Ella':'Mila'}.</p>${i<4?'<button class="primary" data-action="next">Continue →</button>':'<a class="primary" href="./" style="text-decoration:none">Return home</a>'}</div>`}
function renderMission(){const i=state.activeMission,m=ADDITION_CHAIN.missions[i];if(sessionMissionId!==m.id)loadSession(m.id);$('#missionEyebrow').textContent=`MISSION ${m.number} · ${m.kind.replace('-',' ').toUpperCase()}`;$('#missionTitle').textContent=m.title;$('#missionObjective').textContent=m.objective;$('#missionTime').textContent=`ABOUT ${m.minutes} MIN`;feedback('');if(done(i)){renderComplete(i);return}if(i===0)renderDiagnostic();else if(i===1)renderBridge();else if(i===2)renderSubtract();else if(i===3)renderCheck();else renderFresh()}
function renderNav(){$('#missionNav').innerHTML=ADDITION_CHAIN.missions.map((m,i)=>`<button class="mission-button ${i===state.activeMission?'active':''} ${unlocked(i)?'':'locked'}" data-mission="${i}" ${unlocked(i)?'':'disabled'}><span class="mission-number">${m.number}</span><span class="mission-label">${esc(m.title)}</span><span class="mission-state">${done(i)?'✓':unlocked(i)?'›':'◌'}</span></button>`).join('');document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{state.activeMission=Number(b.dataset.mission);sessionMissionId=null;save();render()})}
function renderTrack(){const t=track();$('#trackCard').innerHTML=`<strong>Current depth: ${t.label}</strong><span>${t.description}</span><select id="trackSelect" aria-label="Learning depth">${Object.values(ADDITION_TRACKS).map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${x.label}</option>`).join('')}</select><small>Changing depth restarts this review path so evidence is not mixed.</small>`;$('#trackSelect').onchange=e=>{state={...createBlankAdditionLearner(),track:e.target.value,family:state.family};sessionMissionId=null;save();render()}}
function renderEvidence(){const labels={friendly:'Choose a friendly number',decompose:'Split & compensate',inverse:'Check with inverse',explanation:'Explain & transfer'};$('#evidenceGrid').innerHTML=Object.entries(labels).map(([k,v])=>`<div class="evidence-item"><header><span>${v}</span><span>${state.evidence[k]==='independent'?'Independent':state.evidence[k]==='learning'?'Learning':'Not checked'}</span></header></div>`).join('')}
function renderFamily(){$('#helpNote').value=state.family.help;$('#explainNote').value=state.family.explain;$('#continueNote').value=state.family.continue}
function render(){ensureState();$('#learnerSelect').value=learner;renderTrack();renderNav();renderEvidence();renderFamily();renderMission()}

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='start'){state.missions['addition-start']={complete:true,score:state.diagnostic.score,completedAt:new Date().toISOString()};state.activeMission=1;sessionMissionId=null;save();render()}else if(a==='next'){state.activeMission=Math.min(4,state.activeMission+1);sessionMissionId=null;save();render()}else if(a==='hint'){hintLevel++;saveSession();renderMission()}else if(a==='preview'){state.previewFresh=true;save();render()}});
$('#learnerSelect').onchange=e=>{learner=e.target.value;state=readStore()[learner]||createBlankAdditionLearner();sessionMissionId=null;ensureState();save();render()};
for(const[id,key]of[['helpNote','help'],['explainNote','explain'],['continueNote','continue']])$('#'+id).addEventListener('input',e=>{state.family[key]=e.target.value;save()});
$('#resetPath').onclick=()=>{if(confirm(`Reset the addition and subtraction review path for ${learner==='a'?'Ella':'Mila'}?`)){state=createBlankAdditionLearner();sessionMissionId=null;save();render()}};
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js'));
ensureState();render();
